/* Owner-provided RPG attributes and a shared-node skill graph. */
(()=>{
 const tr=(id,en)=>document.documentElement.lang==='en'?en:id;
 const skills=portfolioData.skills,branches=portfolioData.skillBranches,host=document.querySelector('[data-screen="skillset"]'),old=host.querySelector('.journeygrid');
 const rated=n=>typeof n==='number'&&Number.isFinite(n);
 const score=n=>new Intl.NumberFormat(document.documentElement.lang==='en'?'en-US':'id-ID',{maximumFractionDigits:1}).format(n);
 const level=n=>!rated(n)?tr('Belum dinilai','Not yet rated'):n===5?'Specialist':n===4.5?'Advanced → Specialist':n>=4?'Advanced':n===3.5?'Independent → Advanced':n>=3?'Independent':n>=2?'Practicing':'Exploring';
 const meter=(n,label)=>`<div class="rpg-meter" ${rated(n)?`role="meter" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${n}"`:`role="img" aria-label="${tr('Belum dinilai','Not yet rated')}"`}><div class="rpg-segments" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i><span style="width:${rated(n)?Math.max(0,Math.min(1,n-i))*100:0}%"></span></i>`).join('')}</div><b>${rated(n)?score(n)+' / 5':'—'}</b></div>`;
 const icon=s=>`<img src="assets/skills/${esc(s.icon)}.${s.icon==='flow'?'png':'svg'}" alt="" loading="lazy">`;
 let branch='all',opener,frame;
 const board=document.createElement('section');board.className='rpg-skills';host.insertBefore(board,old);
 const details=document.createElement('details');details.className='journey-details';details.innerHTML='<summary>Pengalaman, pendidikan & ringkasan keahlian <span>+</span></summary>';host.insertBefore(details,old);details.append(old);old.querySelector('.skills')?.remove();
 const dialog=document.createElement('dialog');dialog.className='skill-dialog rpg-dialog';dialog.setAttribute('aria-labelledby','rpg-dialog-title');document.body.append(dialog);
 function render(){const approach=portfolioData.developmentApproach;
 const abilities=(portfolioData.coreAbilities||[]).map(item=>`<article class="capability-card"><h3>${esc(document.documentElement.lang==='en'?item.enName:item.name)}</h3><p>${esc(document.documentElement.lang==='en'?item.enDescription:item.description)}</p><small>${tr('PENERAPAN','APPLIED IN')}: ${esc(item.evidence)}</small></article>`).join('');
 const evidence=(portfolioData.productivityEvidence||[]).map(item=>`<article class="productivity-card"><div><strong>${esc(item.value)}</strong><small>${esc(item.unit)}</small></div><h3>${esc(document.documentElement.lang==='en'?item.enTitle:item.title)}</h3><p>${esc(document.documentElement.lang==='en'?item.enDetail:item.detail)}</p></article>`).join('');
 const proofPanel=`<section class="core-abilities" aria-label="${tr('Kemampuan inti','Core abilities')}"><div class="capability-heading"><span class="eyebrow">CORE ABILITIES</span><h2>${tr('Kemampuan inti, bukan hanya daftar tools.','Capabilities beyond a tool list.')}</h2><p>${tr('Saya merangkai strategi bisnis, kreativitas, kepemimpinan, dan AI untuk menyelesaikan pekerjaan.','I combine business strategy, creativity, leadership and AI to deliver work.')}</p></div><div class="capabilities-grid">${abilities}</div></section><section class="productivity-proof" aria-label="${tr('Bukti cara kerja','Work examples')}"><div class="capability-heading"><span class="eyebrow">WORK EVIDENCE</span><h2>${tr('Contoh hasil kerja terukur.','Concrete examples of delivered work.')}</h2></div><div class="productivity-grid">${evidence}</div><p class="rpg-disclaimer">${tr('Angka berdasarkan laporan pengerjaan pribadi; bukan metrik dampak bisnis, tolok ukur industri, atau jaminan pekerjaan lain selesai dengan kecepatan yang sama.','Figures are self-reported work examples, not business-impact metrics, industry benchmarks or guarantees for future projects.')}</p></section>`;
 board.innerHTML=`<div class="rpg-intro"><div><span class="eyebrow">CHARACTER ATTRIBUTES</span><h2>${tr('Kreativitas bertemu kemampuan membangun.','Creativity meets the ability to build.')}</h2></div><span class="rpg-assessment">${tr('PENILAIAN PRIBADI','SELF-ASSESSMENT')}</span></div><p class="rpg-disclaimer">${tr('Nilai diberikan oleh Muhammad Subhi. Bar menggambarkan penguasaan pribadi, bukan sertifikasi.','Scores are supplied by Muhammad Subhi. Bars represent personal proficiency, not certifications.')}</p><div class="rpg-attributes">${portfolioData.rpgAttributes.map((a,i)=>`<article class="rpg-attribute" style="--stat-color:${['#bc8a30','#4b8e92','#7f78a9','#698b68','#a87950'][i]}"><div class="rpg-stat-heading"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(a.name)}</h3></div>${meter(a.rating,a.name)}<strong>${level(a.rating)}</strong><p>${esc(document.documentElement.lang==='en'?a.enDescription:a.description)}</p></article>`).join('')}</div>${proofPanel}<div class="rpg-graph-heading"><div><span class="eyebrow">SKILL TREE</span><h2>${tr('Satu tool. Banyak kemampuan.','One tool. Many capabilities.')}</h2><p>${tr('Pilih cabang untuk melihat koneksinya. Pilih tool untuk membuka status dan penerapannya.','Select a branch to see its connections. Select a tool to inspect its status and application.')}</p></div><button class="rpg-all" data-rpg-branch="all" aria-pressed="${branch==='all'}">${tr('Semua cabang','All branches')}</button></div><div class="rpg-board"><svg class="rpg-connections" aria-hidden="true"></svg><div class="rpg-root"><span class="personal-monogram">MS</span><div><b>Muhammad Subhi</b><small>DESIGN · BUILD · CREATE</small></div></div><div class="rpg-branches" role="group" aria-label="${tr('Pilih cabang keahlian','Choose a skill branch')}">${branches.map((b,i)=>`<button class="rpg-branch ${branch===b.id?'selected':''}" data-rpg-branch="${b.id}" aria-pressed="${branch===b.id}"><small>${String(i+1).padStart(2,'0')} / ${skills.filter(s=>s.categories.includes(b.id)).length} tools</small><b>${esc(document.documentElement.lang==='en'?b.enName:b.name)}</b></button>`).join('')}</div><p class="rpg-node-note">${tr(skills.length+' tools & platform · setiap tool satu node',skills.length+' tools & platforms · one node per tool')}</p><div class="rpg-tool-grid">${skills.map((s,i)=>`<button class="rpg-tool ${branch!=='all'&&!s.categories.includes(branch)?'unrelated':''}" data-rpg-skill="${i}" aria-label="${esc(s.name)} · ${rated(s.rating)?score(s.rating)+' / 5':tr('belum dinilai','not yet rated')}"><span class="rpg-emblem">${icon(s)}</span><h3>${esc(s.name)}</h3>${meter(s.rating,s.name)}<small>${level(s.rating)}</small><span class="rpg-inspect">${tr('Buka skill','Inspect skill')} ↗</span></button>`).join('')}</div></div><div class="rpg-level-legend"><span>1 Exploring</span><span>2 Practicing</span><span>3 Independent</span><span>4 Advanced</span><span>5 Specialist</span></div><article class="rpg-approach"><span class="eyebrow">BUILD APPROACH</span><h3>${esc(approach.title)}</h3><p>${esc(document.documentElement.lang==='en'?approach.enDescription:approach.description)}</p></article>`;scheduleLines()}
 function scheduleLines(){cancelAnimationFrame(frame);frame=requestAnimationFrame(drawLines)}
 function drawLines(){if(host.hidden)return;const graph=board.querySelector('.rpg-board'),svg=board.querySelector('.rpg-connections');if(!graph||!svg)return;const rect=graph.getBoundingClientRect(),root=board.querySelector('.rpg-root').getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${rect.width} ${rect.height}`);let paths='';const line=(x1,y1,x2,y2,active)=>{const bend=Math.max(25,Math.min(100,(y2-y1)/2));return `<path class="${active?'is-active':''}" d="M ${x1} ${y1} C ${x1} ${y1+bend},${x2} ${y2-bend},${x2} ${y2}"/>`};branches.forEach(b=>{const br=board.querySelector(`.rpg-branch[data-rpg-branch="${b.id}"]`).getBoundingClientRect();const on=branch===b.id;paths+=line(root.x+root.width/2-rect.x,root.bottom-rect.y,br.x+br.width/2-rect.x,br.top-rect.y,on);if(branch!=='all'&&!on)return;skills.forEach((s,i)=>{if(!s.categories.includes(b.id))return;const node=board.querySelector(`[data-rpg-skill="${i}"]`).getBoundingClientRect();paths+=line(br.x+br.width/2-rect.x,br.bottom-rect.y,node.x+node.width/2-rect.x,node.top-rect.y,on)})});svg.innerHTML=paths}
 function close(){dialog.close();opener?.focus({preventScroll:true})}
 function openSkill(index){const s=skills[index],related=(s.relatedProjects||[]).map(id=>portfolioData.projects.find(p=>p.id===id)).filter(p=>p&&p.permission==='Boleh ditampilkan');dialog.innerHTML=`<button class="skill-close" aria-label="${tr('Tutup detail skill','Close skill details')}">×</button><span class="eyebrow">SKILL STATUS</span><div class="rpg-dialog-icon">${icon(s)}</div><h2 id="rpg-dialog-title">${esc(s.name)}</h2>${meter(s.rating,s.name)}<p class="rpg-dialog-level">${level(s.rating)}</p><div class="rpg-dialog-branches">${s.categories.map(id=>{const b=branches.find(b=>b.id===id);return `<span>${esc(document.documentElement.lang==='en'?b.enName:b.name)}</span>`}).join('')}</div><p>${esc(document.documentElement.lang==='en'?s.enApplication:s.application)}</p>${s.evidenceNote?`<p class="evidence-context">${esc(tr(...s.evidenceNote))}</p>`:''}<div class="rpg-evidence"><small>${tr('KARYA TERKAIT','RELATED WORK')}</small>${related.length?related.sort((a,b)=>Number(!!b.portfolioEvidence)-Number(!!a.portfolioEvidence)).slice(0,5).map(p=>`<button data-rpg-project="${esc(p.id)}">${esc(p.brand)} <span>↗</span></button>`).join(''):`<p>${tr('Kemampuan pada tool ini dijelaskan melalui cakupan penggunaan di atas. Jelajahi karya pilihan untuk menilai hasil lintas kemampuan.','This tool’s capability is described by the usage scope above. Explore selected work to assess the combined output.')}</p>`}</div><p class="skill-modal-note">${rated(s.rating)?tr('Penilaian pribadi dari pemilik portofolio.','Self-assessment supplied by the portfolio owner.'):tr('Tool digunakan, tetapi belum diberi nilai penguasaan.','This tool is used, but no proficiency score has been supplied.')}</p><button class="skill-done">${tr('Kembali ke skill tree ←','Back to skill tree ←')}</button>`;dialog.showModal();dialog.querySelector('.skill-close').focus()}
 board.addEventListener('click',e=>{const b=e.target.closest('[data-rpg-branch]'),s=e.target.closest('[data-rpg-skill]');if(b){branch=b.dataset.rpgBranch;render();board.querySelector(`[data-rpg-branch="${branch}"]`)?.focus({preventScroll:true})}else if(s){opener=s;openSkill(+s.dataset.rpgSkill)}});
 dialog.addEventListener('click',e=>{const p=e.target.closest('[data-rpg-project]');if(p){close();projectQuery='';const search=document.querySelector('#project-search');if(search)search.value='';filter='all';active=projects.findIndex(x=>x.id===p.dataset.rpgProject);filter=projects[active]?.contentManagement?'social':'all';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});if(active<0)return;render();location.hash='portofolio';return}if(e.target.closest('.skill-close,.skill-done'))close()});
 dialog.addEventListener('cancel',e=>{e.preventDefault();close()});
 window.addEventListener('languagechange',()=>{render();if(dialog.open)close()});window.addEventListener('resize',scheduleLines);window.addEventListener('hashchange',scheduleLines);new ResizeObserver(scheduleLines).observe(board);
 render();
})();
